local _, ZoneLore = ...

ZoneLore.Zones = {
	[947] = {
		name = "Azeroth",
		short = "At the heart of the world sleeps a titan who has not yet woken.",
		full = "At the heart of the world sleeps a titan who has not yet woken. Long before mortals drew breath, Azeroth's worldsoul drew in so much raw life that the elements ran wild, until the Old Gods fell from the dark and rooted themselves in the earth, raising their Black Empire in silence. To save the worldsoul, the Pantheon of Order tore the Old God Y'Shaarj bodily from the world's flesh. The wound would not close. The Keepers sealed it with wards, and the arcane blood that pooled there became the Well of Eternity - the same power the Highborne later abused until it tore the land into four broken continents and drowned four-fifths of it beneath the sea.\n\nThe world has bled again since, cracking open along fault lines of light, its pain rising as storms and quakes across every shore. Those who once guarded it spent their own power holding the Old Gods back, then stepped down, passing the duty to others. What stands now is a world still healing an old wound at its core.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Durotar, the land named after Thrall's father, Durotan, lies on the eastern coast of Kalimdor. It borders the Barrens to the west and the coastal lands of Azshara to the north.",
		full = "Durotar, the land named after Thrall's father, Durotan, lies on the eastern coast of Kalimdor. It borders the Barrens to the west and the coastal lands of Azshara to the north. The land of Durotar is rocky, and the soil is cracked and red, not unlike the orcs' homeland of Draenor. The land has many crags and canyons, where various dangerous creatures take residence. It is a harsh land to survive in; it is very dry and hot, and the vegetation and freshwater access is sparse. The orcs, however, see a harsh beauty in the land that reminds them of their home world. Durotar is a proving ground for young orcs, who are sent to the Valley of Trials to complete several rites of passage before they are considered fit for the challenges that lie ahead. Durotar is the new homeland of the orcs and the site of the orcs' principal city of Orgrimmar. While the orcs founded their city of Orgrimmar here, Durotar has become something of a haven for all of the Horde races, especially the trolls.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "Mulgore",
		short = "The plains of Mulgore lie shut behind a ring of mountains, reachable only through the pass to the east.",
		full = "The plains of Mulgore lie shut behind a ring of mountains, reachable only through the pass to the east. For hundreds of years the tauren tribes wandered here without a homeland, driven from place to place by the centaur who claimed the grasslands as their own.\n\nThat ended when the orcs came to Kalimdor. Cairne Bloodhoof looked upon Thrall and his people and saw kindred spirits, honorable and strong. With their aid the Bloodhoof tribe turned back the centaur and took Mulgore for the tauren at last. Upon the windswept mesa that rose above the plains, Cairne raised a refuge open to every tribe, and named it Thunder Bluff. Scattered tauren came together under his rule, and none doubted he was the one to lead them.\n\nYoung tauren still ride out into the grass to prove themselves in the Great Hunt, testing their skill against the wild beasts of the plains, as every tauren has always done to claim their place as a child of the Earth Mother.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
	},
	[1413] = {
		name = "The Barrens",
		short = "The dust here was not always dust. Once this was forest, tended by kaldorei who raised the outpost of Then'Ralore, and it is said the demigod Lo'Gosh stood here against the Burning Legion in the War of the Ancients.",
		full = "The dust here was not always dust. Once this was forest, tended by kaldorei who raised the outpost of Then'Ralore, and it is said the demigod Lo'Gosh stood here against the Burning Legion in the War of the Ancients. The Great Sundering ended all that, and the green valley became the sun-scorched plain it is now.\n\nFor generations the tauren wandered these plains, hunting kodo and thunder lizard, seeking the Earth Mother's wisdom, forever hounded by centaur who hunted them for sport. They fought back but never for love of war; when the horse-men came, they struck their tents and moved on rather than throw lives away. A year of peace, a year of war -- that was tauren life, until Thrall's orcs and the Darkspear trolls landed and marched with the Bloodhoof tauren against the centaur. After the Legion's fall at Mount Hyjal, Thrall claimed the eastern Barrens, drove off the Razormane quilboar, and named that land Durotar, raising Orgrimmar as its capital.\n\nThe land holds older griefs too: it is said a man named Dethorin found his love Allurana in another's arms, and his cry tore the axe Killmaim up out of the sand -- the same blade he used to kill her.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "Kalimdor",
		short = "For ten thousand years after the world was broken, Kalimdor kept itself hidden. The night elves who remained drew a veil of mist over the whole continent, and ships passed and saw nothing.",
		full = "For ten thousand years after the world was broken, Kalimdor kept itself hidden. The night elves who remained drew a veil of mist over the whole continent, and ships passed and saw nothing. Among humans it survived only as legend, a broken land sunk during the Sundering, without location or shape.\n\nBut it was not entirely lost. Night elves such as Emmarel Shadewarden slipped through the mist to visit the quel'dorei in the years that followed, and so the high elves of Quel'Thalas alone knew the legend was true.\n\nEven when the Third War came, most humans still refused to believe Kalimdor existed. Only a few heeded Medivh's warning and sailed west into the mist, Thrall's Horde among them, Jaina Proudmoore's expedition behind. What they found was no legend but a whole continent, ice in its north, desert in its south, night elves still holding the woods between, having waited out every age alone.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Eastern Kingdoms",
		short = "The land now called the Eastern Kingdoms was not always separate from the rest of the world.",
		full = "The land now called the Eastern Kingdoms was not always separate from the rest of the world. It was once part of a single continent, Kalimdor, before the Great Sundering tore the world apart and left this ground broken into pieces of its own: Azeroth, Khaz Modan, and Lordaeron, with the elven land of Quel'Thalas clinging to the northern edge of Lordaeron, neither fully its own continent nor quite part of the rest.\n\nThrough the heart of it runs the spine of Khaz Modan, mountains that divide the land as surely as the sundering once divided the world, alongside the lesser heights of the Redridge Mountains. It is old ground, home to dwarves, gnomes, humans, elves, the Forsaken, and the worgen, with orcs, goblins, draenei, naga, and ogres besides.\n\nTo stand anywhere in the Eastern Kingdoms is to stand on a fragment of something whole that broke apart long before any of the kingdoms now built upon it ever had a name.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Alterac Mountains",
		short = "Rain never quite stops falling on these peaks. Once the Alteraci tribe held these slopes, until their leader Ignaeus lost a duel to King Thoradin and bent the knee to Arathor.",
		full = "Rain never quite stops falling on these peaks. Once the Alteraci tribe held these slopes, until their leader Ignaeus lost a duel to King Thoradin and bent the knee to Arathor. From that surrender grew a city-state that came to rule much of the northlands from among the summits, its name given to the whole range.\n\nThat kingdom betrayed the Alliance of Lordaeron during the Second War, and Lordaeron's armies marched into the mountains to strike Alterac at its heart. The city fell, and its ruins were later claimed by the Crushridge ogres under their warlord Mug'thol. The royal line did not vanish quietly: the exiled prince Aliden Perenolde returned in the guise of the Syndicate, a company of fallen nobles and rogues who still hold Strahnbrad and other corners of the range, warring endlessly with the ogres.\n\nDalaran, too, once stood here, a city-state of its own among these heights, before it was sealed within an impregnable shell and lifted whole into the sky, leaving only a crater behind.\n\nWhat Alliance presence remains clings to the entrances of Alterac Valley, where Stormpike dwarves and Frostwolf orcs still contest the frontier.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "Arathi Highlands",
		short = "King Thoradin came to this arid country following a dream, and here he raised Strom, first capital of the united tribes of Arathor, building a great wall to keep the forest ambushes of the Amani trolls from ever reaching it.",
		full = "King Thoradin came to this arid country following a dream, and here he raised Strom, first capital of the united tribes of Arathor, building a great wall to keep the forest ambushes of the Amani trolls from ever reaching it. For a thousand years Strom stood as the heart of humanity, but the land that made it safe also starved it of resources, and when the noble houses drifted away to richer country, only a handful of ruling families remained. From that remnant rose Stromgarde.\n\nThe village that became Hammerfall was turned into an internment camp for captured orcs, until Thrall and Orgrim Doomhammer broke it open to free their kin. Long after, the Horde reclaimed that ground and named their base Hammerfall in memory of the fallen warchief.\n\nStromgarde Keep itself later fell to the Syndicate and the Boulderfist ogres, its defenders scattered into a canyon they now call Refuge Pointe, and it was years before the people of Stromgarde returned to rebuild what had been theirs.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "Badlands",
		short = "The Badlands is a country cracked open by heat, all dry earth and canyon and broken stone, where little survives beyond coyotes, cougars, and buzzards.",
		full = "The Badlands is a country cracked open by heat, all dry earth and canyon and broken stone, where little survives beyond coyotes, cougars, and buzzards.\n\nIn the northern reaches lie the ruins of Uldaman, workings of the earthen, the ancient race from which the dwarves trace their origin. When the ruin was unearthed it drew Ironforge prospectors of the Explorer's League by the score, chasing the first clues to their own beginnings. But the Stonevault troggs, roused after millennia of slumber, fell upon them, slaughtering the explorers and turning the buried city into a charnel house they now guard without mercy. South of Uldaman the Dark Iron dwarves hold a fortress of their own, warring with ogres and drakes for the wasteland between.\n\nWarchief Thrall himself sent forth the Kargath Expeditionary Force to slay Rend Blackhand of the renegade Blackrock clan, and from that campaign rose Kargath, the only Horde outpost standing in all of Khaz Modan.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "Blasted Lands",
		short = "The red clay underfoot did not come by its color naturally. It was tan once, part of a dark fen called the Black Morass, before the Orcish Horde tore the Dark Portal open here and marched north to fall upon Stormwind.",
		full = "The red clay underfoot did not come by its color naturally. It was tan once, part of a dark fen called the Black Morass, before the Orcish Horde tore the Dark Portal open here and marched north to fall upon Stormwind. The land has been burnt and dead ever since, lightning striking without cloud or reason.\n\nAfter the portal's first destruction, Archmage Khadgar and the Kirin Tor raised Nethergarde Keep to watch the scar it left. Peace lasted two years before the Horde of Draenor reopened the gateway and besieged the keep. The Alliance sent the Sons of Lothar through the portal itself, and when Ner'zhul's ritual began unmaking Draenor behind them, Khadgar and his magi turned the Skull of Gul'dan against the portal's stone frame and blew it apart, severing the bridge between worlds. Those orcs who fled through in time surrendered and were carried off to Lordaeron's internment camps.\n\nNethergarde Keep still stands at the one usable road north, its mages and paladins uncheerful and exacting, watching the portal by day and the ogre tribes by night.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "Tirisfal Glades",
		short = "The sky over Tirisfal Glades has hung sickly green for years, the trees clinging to whatever life the plague left them.",
		full = "The sky over Tirisfal Glades has hung sickly green for years, the trees clinging to whatever life the plague left them. Once these were peaceful farms under King Terenas, generations living quietly among the mills and pumpkin fields. That ended when Arthas Menethil ransacked Lordaeron and swept the plague through the countryside, killing its people and raising them as slaves to the Lich King. Mass graves still mark where the dead were too numerous to bury properly. At the Balnir Farmstead, Arthas raised his own dead horse, Invincible, as a skeletal steed, and it was near that same field, months later, that Sylvanas Windrunner turned her banshees against him and put a poisoned arrow in the death knight before Kel'Thuzad's skeletons drove her off.\n\nOut of that ruin came the Forsaken, Sylvanas's free-willed dead, who claimed the land as their own. Their enemies never left it: the Scarlet Crusade holds the old Scarlet Monastery in the north, fanatics who burn and hunt anything not human.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Silverpine Forest",
		short = "Silverpine Forest, or simply Silverpine, is a vast, ancient wood that runs along Lordaeron's rugged western coast. The land ranges from fairly flat to hilly, and is nestled among even taller mountains.",
		full = "Silverpine Forest, or simply Silverpine, is a vast, ancient wood that runs along Lordaeron's rugged western coast. The land ranges from fairly flat to hilly, and is nestled among even taller mountains. The forest is eerily silent save for the occasional unnatural howling echoing among the trees. Mossy overhangs shiver in the cold breeze, and the trees are all sickly or dying. Dilapidated farmsteads and abandoned mines dot the land, home now to the darker denizens of the woods.\n\nThis woodland is haunted and wild, characterized by its tall, silver-barked pines towering over grassy knolls. The Alliance once protected Silverpine Forest when it was verdant and lively. Now the place is shrouded in ghostly mists. Forsaken control the northern forest and constantly clash with the wretched Rot Hide gnolls. What remains of the human population retains control of the southern forest, but they are desperate and their forces thinly stretched. Dalaran sends frequent expeditions into Silverpine to defend these people and study the undead plague and worgen curse -- a mysterious affliction that causes its victims to transform into bloodthirsty, lycanthropic worgen when the moon rises.\n\nGilneas and the Hillsbrad Foothills border the forest to the south, while Tirisfal Glades lays to the north. Lordamere Lake serves as Silverpine's eastern border.\n\nThough the territory belongs to the Forsaken, their claim is disputed by the wizards of Dalaran and agents of the Scourge who have taken possession of some of the ruined fields and steadings. Rothide gnolls operate from the mysterious Fenris Isle, and fiercely attack anyone who dares approach their dealings. In the southwest lays Pyrewood Village, whose people have fallen under archmage Arugal's curse, transforming into bloodthirsty worgen at night-time. Arugal makes his home in the nearby darkened towers of Shadowfang Keep.\n\nSilverpine Forest frequently sees battle, as Alliance forces from Southshore journey to the forsaken woods to attack the Sepulcher or enter Shadowfang. It is the edge of the Forsaken homeland, and the southernmost point where effects of the undead plague can be seen in the plant life.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Western Plaguelands",
		short = "The Western Plaguelands are located in northern Lordaeron, wedged between Tirisfal Glades to the west, the Eastern Plaguelands to the east, and the Alterac Mountains to the south.",
		full = "The Western Plaguelands are located in northern Lordaeron, wedged between Tirisfal Glades to the west, the Eastern Plaguelands to the east, and the Alterac Mountains to the south. It is filled with a smoky gray mist and the creatures here are blighted and sick, angrily attacking anyone who wanders too close with surprising ferocity. The land is also home to countless undead who infest the ruins of Andorhal, the four cauldron fields, and Sorrow Hill. The Scarlet Crusade has a significant holding in and around Hearthglen to the north, and the Alliance has settled in the small Chillwind Camp to the south.\n\nLike their eastern counterparts, the Western Plaguelands were once fertile and beautiful but are now gray, blighted and noxious. Undead wander the land and haunt the abandoned towns and farmsteads. The largest Scourge city here is Andorhal, beneath which is an underground complex housing the undead's School of Necromancy. The Scarlet Crusade strikes against the Scourge from Hearthglen. The only place of any sanity in the Western Plaguelands is Uther's Tomb, a consecrated monument to the fallen hero Uther Lightbringer.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Eastern Plaguelands",
		short = "Once this was Eastweald, farms and villages governed from Stratholme, second city of Lordaeron. It was Stratholme that saw the kingdom's ruin.",
		full = "Once this was Eastweald, farms and villages governed from Stratholme, second city of Lordaeron. It was Stratholme that saw the kingdom's ruin. When Prince Arthas came hunting the source of the plague, he found the city's people already infected. Uther of the Silver Hand refused to help him purge it, so Arthas stripped him of command, disbanded the Silver Hand outright, and put the city to the torch himself. He went on to kill his own father and bring down the kingdom entire; the blight that followed spread out from Stratholme to swallow the land north of it.\n\nOut of that ruin came Alexandros Mograine, who gathered the shattered Silver Hand into a Crusade to retake the kingdom from both Scourge and Forsaken. After his death the Crusade split: the Argent Dawn made its stand at Light's Hope Chapel, a rare island of welcome in a poisoned land, while the rest hardened into the Scarlet Crusade, fighting the Scourge with a fervor that spares no outsider either.\n\nStratholme still stands under Kel'Thuzad's rule, its ground brown and sick, its trees swollen into mushrooms, its air thick with orange mist.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Hillsbrad Foothills",
		short = "Hillsbrad's soil is rich and its hills green, and travelers say it is what all of Lordaeron looked like before the Plague came.",
		full = "Hillsbrad's soil is rich and its hills green, and travelers say it is what all of Lordaeron looked like before the Plague came. That is its cruelty as much as its comfort: the land remembers what was lost everywhere else, while the people who hold it fight the same war that ruined the rest.\n\nAt the outset of the Second War, orcish raiders struck its coastal towns, and Orgrim Doomhammer himself rode against Durnholde Keep to free Zul'jin from its cells. Decades later it was Thrall who came through these hills, gathering the scattered orcish clans and freeing Grommash Hellscream's Warsong before slipping into Southshore by night to steal her ships and carry the new Horde across the sea to Kalimdor.\n\nWhat the orcs began, the Forsaken have continued. They claimed Tarren Mill as their southernmost holding and turned it into a staging ground against the humans of Southshore and Hillsbrad Fields, who held fast for the Alliance.\n\nPine woods dot the farmland now, and roads still cross the pastures toward the gloomy Forsaken settlements to the north, as if the land itself were still waiting to see which side keeps it.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "The Hinterlands",
		short = "The Hinterlands, located in the Northern part of the Eastern Kingdoms, are probably most notable for the Wildhammer dwarves who make their residence at Aerie Peak in the west.",
		full = "The Hinterlands, located in the Northern part of the Eastern Kingdoms, are probably most notable for the Wildhammer dwarves who make their residence at Aerie Peak in the west. The Wildhammers have always been staunch allies of the Alliance. It is from the Hinterlands that these dwarves find and tame their world-renowned gryphons. The Razorbeak gryphons roam wild in this region.\n\nAlso in the Hinterlands is one of the last remaining settlements of the high elves in Lordaeron at the Quel'Danil Lodge.\n\nThe Hinterlands are also home to a large population of forest trolls, which are divided into three separate tribes. The Revantusk tribe is the only one of the three that has declared sides in the Horde/Alliance conflict and support the warchief Thrall of the Horde. The Vilebranch tribe holds residence in the massive troll city of Jintha'Alor as well as the Altar of Zul while the Witherbark tribe holds the smallest influence, hailing from the temples of Shadra'Alor.\n\nIn the northern part of the region is the ancient, massive tree, Seradane where the agents of the Green dragonflight have been corrupted. A massive portal on the side of the tree connects the servants of the Aspect Ysera to her own realm, the Emerald Dream.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "Dun Morogh is a snowy region located between the magma-strewn wasteland of the Searing Gorge to the south, the gentle ridges of Loch Modan to the east, and the swampy Wetlands to the north.",
		full = "Dun Morogh is a snowy region located between the magma-strewn wasteland of the Searing Gorge to the south, the gentle ridges of Loch Modan to the east, and the swampy Wetlands to the north. Dun Morogh is home to both the gnomes of Gnomeregan and the Ironforge dwarves and is the location of the major city of Ironforge. The Khaz Modan mountains surround Dun Morogh on all sides, making it accessible only by certain passes that are currently watched over by dwarven troops.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "Searing Gorge",
		short = "Once this was green land, part of the Redridge Mountains, before it was burned to slag by a single act of desperation.",
		full = "Once this was green land, part of the Redridge Mountains, before it was burned to slag by a single act of desperation.\n\nSorcerer-Thane Thaurissan led the Dark Iron dwarves in the War of the Three Hammers, and when the war turned against him, he and seven of his most trusted dwarves reached beneath the world for a power to save them. What answered was not a servant but the Firelord Ragnaros himself. Blackrock Mountain tore up out of the earth in that instant, crushing Thaurissan's capital to rubble. The scorched steppes to the south became the Burning Steppes; this blackened valley became the Searing Gorge.\n\nThe Dark Iron survivors rebuilt in the mountain above, and turned the floor of the gorge into a vast excavation, the Cauldron, mined below by slaves taken from their captured enemies.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Burning Steppes",
		short = "The sky over the Burning Steppes never loses its red hue, lit by sporadic eruptions from Blackrock Mountain, and the ground never cools.",
		full = "The sky over the Burning Steppes never loses its red hue, lit by sporadic eruptions from Blackrock Mountain, and the ground never cools. Two hundred years before the Dark Portal opened, Dark Iron dwarves came here in exile from Ironforge. Their Sorcerer-Thane, Thaurissan, sought to summon elemental minions to win the War of the Three Hammers against the Bronzebeard and Wildhammer clans. What answered was not a minion but Ragnaros the Firelord, once banished by the titans. His arrival melted the mountains around him, raised a volcano at the blast's heart, and destroyed the dwarves who had summoned him. What lay north of that new peak became the Searing Gorge; what lay south, the Burning Steppes, scarred ever since.\n\nOrcs settled the volcano's slopes during the First War and held Blackrock Spire as a stronghold through the Second, until the Alliance besieged it in the war's last days. The Blackrock orcs returned afterward and remain there still, following the old brutal ways from before Thrall's truce. Black dragons under Nefarion hold the spire's upper levels, Dark Iron dwarves grip its deeps, and it is said Ragnaros yet broods somewhere beneath it all.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Elwynn Forest",
		short = "When the orcs came in the First War, thousands marched through Elwynn to surround Stormwind, cutting it off from everything but the sea.",
		full = "When the orcs came in the First War, thousands marched through Elwynn to surround Stormwind, cutting it off from everything but the sea. Knight Champion Anduin Lothar led the Knights of Stormwind in a charge through the forest itself, striking the orcish rearguard by surprise and scattering them. It bought the city time, but not enough. Warchief Blackhand soon took Goldshire and Moonbrook, the last towns standing between the Horde and the king, and Stormwind Keep was sacked. Lothar led the survivors to the sea and away to Lordaeron, and the ruins of the city belonged for a time to the Stormreaver clan. Scattered orcish catapults still lie broken and rotting across the region, the only reminders left of that occupation.\n\nNorthshire Vineyards, east of the city, were once the pride of Stormwind's farmers. When the Stonemasons Guild went unpaid for the years they spent rebuilding the ruined capital, and the nobles disbanded them rather than settle the debt, Guildmaster Edwin VanCleef's fury spread into riots that killed Queen Tiffin Ellerian Wrynn and birthed the Defias Brotherhood. The Brotherhood drove the farmers from Northshire and occupied its fields.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Deadwind Pass",
		short = "Deadwind Pass is a contested zone located in central Azeroth, joining the southeastern reaches of the Kingdom of Stormwind (via Duskwood) from the east to the Swamp of Sorrows (and, eventually, the Dark Portal in the Blasted Lands) from the west.",
		full = "Deadwind Pass is a contested zone located in central Azeroth, joining the southeastern reaches of the Kingdom of Stormwind (via Duskwood) from the east to the Swamp of Sorrows (and, eventually, the Dark Portal in the Blasted Lands) from the west. It was, a score of years ago, considered a part of the Redridge Mountains.\n\nThe Ivory Tower of Karazhan, once the dark wizard Medivh's seat of power, stands in the center of this jagged region and leaks evil magic into the land. The trees are petrified and leafless, and a terrible wind keens through the canyon. Ogres, demons, undead and a few human gypsies roam the interior. Deadwind Pass connects Duskwood and the Swamp of Sorrows, and travelers are advised to move quickly -- whispers tell that a new force has claimed the Ivory Tower, and that the ogres and demons are under its sway.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Duskwood",
		short = "Duskwood is located in the southern-central part of Azeroth, south of Elwynn Forest, east of Westfall, west of Deadwind Pass, and north of Stranglethorn Vale.",
		full = "Duskwood is located in the southern-central part of Azeroth, south of Elwynn Forest, east of Westfall, west of Deadwind Pass, and north of Stranglethorn Vale. Technically part of the Alliance and under Stormwind's protection, its distance from the mighty fortress and its close proximity to more malevolent forces in the south and east make it a realm of horror. Due to events central to the Scythe of Elune, Duskwood is a cursed, dying land. Beneath the eternal blanket of darkness which gave Duskwood its current name, the Scythe's effects have transformed what was once a beautiful part of Elwynn Forest into a land covered in gnarled trees and inhabited by the hideous undead and extradimensional Worgen, brought along with the black fog hanging over the woods. Ogres moving in from Deadwind Pass have brought up even more problems.\n\nLong betrayed and abandoned by Stormwind, Duskwood is inhabited by a defiant people who still cling to their holdings in the face of overwhelming adversity. On all sides lurk dangerous creatures, from skeletal warriors and ghouls to ferocious worgen and some of the most powerful members of the Defias Brotherhood. The militia of Duskwood, known as the Night Watch, patrol the main thoroughfare and protect Darkshire, wary of anything moving through the shadows.\n\nThe most prominent geographical feature of Duskwood is an ancient and long-dead volcano crater. The crater teems with life, and features one of the Great Trees with a portal leading into the Emerald Dream. The sleeping druids' influence can be seen on the surrounding land, which is cloaked in a twilight quite different from the rest of Duskwood. The woods also feature several abandoned farmsteads, as well as the prominent Raven Hill Cemetery, which holds the graves of the numerous people who have been killed by wild beasts and undead since the darkness fell.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Loch Modan",
		short = "The gray peaks of Khaz Modan close around Loch Modan on every side, lightly wooded with pine and birch, and at the heart of it all lies the great lake itself, held by the Stonewrought Dam, an engineering marvel unmatched anywhere on Azeroth.",
		full = "The gray peaks of Khaz Modan close around Loch Modan on every side, lightly wooded with pine and birch, and at the heart of it all lies the great lake itself, held by the Stonewrought Dam, an engineering marvel unmatched anywhere on Azeroth.\n\nThe waters look peaceful, but the loch's bottom and islands still hold broken catapults and shattered ballistae, wreckage from the Second War, when the orcs of the Horde swept into the valley and made their stand against the Alliance here. The dwarves of Ironforge held the line, and when the war ended it was they who reclaimed Loch Modan, leaving only the drowned machines of war as evidence of what had happened.\n\nThe dwarves' own digging brought a different enemy to the surface. Troggs, unearthed from the caverns beneath Loch Modan, spread through the surrounding mountains and built crude camps and warrens in the hills, from which they now strike at anyone passing through.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Redridge Mountains",
		short = "The Redridge Mountains, or the Red Ridge Mountains, are located east of Elwynn Forest, northeast of Duskwood, and south of the Burning Steppes.",
		full = "The Redridge Mountains, or the Red Ridge Mountains, are located east of Elwynn Forest, northeast of Duskwood, and south of the Burning Steppes. Although it may be considered contested, Horde characters have no settlements or NPCs and it is thus a place they use mostly for passing through to reach Flame Crest or Stonard.\n\nAn idyllic region of rushing rivers, towering elms and rising elevations, the Redridge Mountains are under Stormwind's protection (though since the second war it is technically independent), and remain one of the last peaceful regions in Azeroth. The people are content and calm, and supply Stormwind with timber, fish, and crops. A force of Blackrock orcs from the Burning Steppes has secured Stonewatch Keep, but so far the orcs keep to themselves. In comparison with Westfall, Redridge is still relatively stable.\n\nOn the northern bank of Lake Everstill is the Alliance town of Lakeshire, the central hub for this faction's adventurers, offering many services and quests, as well as flight paths. As the town is under constant siege by gnolls and Blackrock orcs, adventurers should use extreme caution around this town.\n\nThe enemy-held Stonewatch Keep and Tower of Ilgalar are connected with quests, but are also very dangerous and require a party to handle properly.\n\nThe crossroads known as the Three Corners, located in the southwest corner of the zone, connects the town of Lakeshire with Elwynn, Duskwood and, via the Lakeridge Highway, Stonewatch Keep. The highway itself is quite a dangerous place occupied by dragon whelps, gnolls, murlocs, and wild animals. There are also a few camps located in Redridge -- an orc camp in Render's Valley, Shadow Hide gnoll camps near the Tower of Ilgalar, and murloc camps near the lake. While the lake's surface appears peaceful enough, murlocs reside beneath the waves, and rumours of sightings of a sea monster persist.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Stranglethorn Vale",
		short = "Stranglethorn Vale is a vast jungle south of Duskwood.",
		full = "Stranglethorn Vale is a vast jungle south of Duskwood.\n\nJungle trolls patrol this steaming rainforest. Ancient Gurubashi trolls once ruled the region, and the ruins of their great cities crumble in the jungle's heat and growth. Naga hunt along the coast and vicious animals and plants, including the eponymous strangle-thorns, make travel dangerous. The Arena, a center for gladiatorial games set in a ruined Gurubashi fighting stadium, draws shady characters of all races. The Blackwater Raiders, a vile group of pirates, make their home in Booty Bay, on the Stranglethorn's southern coast.\n\nThe Vale was the primary center of the trolls of the Gurubashi Empire, and their cities were dotted all over the region. After the Empire's fall the cities of the troll empire fell into ruin, although they are still populated by trolls. In recent years, the Humans of Stormwind attempted to forge trade routes through this savage jungle. Though they managed to establish the small port town of Blackwater Cove, they were quickly overwhelmed by a crazed pack of Trolls and driven back to their homeland. In the wake of the Humans' departure, the crafty Goblin Trade Princes arrived on the jungle's shores and quickly set up their mining and deforesting operations. The Goblins have maintained a tenuous hold over these remote facilities, but they remain threatened by the Jungle Trolls' growing obsession with purging their ancient lands of any and all foreign invaders.\n\nStranglethorn is as deadly as it is beautiful. It is inhabited by a large variety of beasts and hostile creatures that low level characters should not face alone. The primary sapient inhabitants are the Bloodscalp and Skullsplitter trolls, in the northwest and east respectively. The troll city of Zul'Gurub sits in a valley in the northeast, which was once the capital of Troll civilization in Stranglethorn. In the north is a small village controlled by the renegade Colonel Kurzen. Other inhabitants include an encampment of ogres. Off the southeast coast is Jaguero Isle, inhabited by the enormous gorilla King Mukla. There is a renegade group of sailors, known as the Bloodsail Buccaneers, who have built camps on the southwestern and southern shores of Stranglethorn Vale. A small population of naga can be found in the southwest, and murlocs inhabit some underwater ruins in the northwest. The Venture Company also has two mining operations in Stranglethorn. In the northwest, the Zandalar Tribe has its base in Yojamba Isle. The water gate from the Deadmines can also been seen north of Yojamba Isle, though it cannot be entered.\n\nThe weekly Stranglethorn Fishing Extravaganza event happens every Sunday from 2-4pm.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Swamp of Sorrows",
		short = "Beneath the black water of the swamp lies a temple that was never meant to be found again.",
		full = "Beneath the black water of the swamp lies a temple that was never meant to be found again.\n\nWhen the Gurubashi Empire broke apart, a renegade sect of trolls called the Atal'ai fled into the marshland and raised the Temple of Atal'Hakkar, where they worshipped the dark loa Hakkar the Soulflayer and labored to drag him bodily into the world. Their rituals twisted the plants and beasts around the temple until the corruption drew the eye of the green dragonflight. Ysera, the Dragon Aspect who watches over dreams, answered the threat herself, drowning the temple beneath the largest bog in the swamp and burying Hakkar's return with it. But she did not trust the Atal'ai to stay broken, and set her consort Eranikus and a host of green dragons to keep endless watch over the sunken ruin. Green dragonspawn still patrol the mire at her command.\n\nThe swamp carries a second scar, from a war of men and orcs. The Horde built the settlements of Rockard, Stonard, and Kyross here as footholds against Stormwind, and the First War broke all three: Rockard and Kyross were destroyed outright, Stonard left in ruins. The land was afterward renamed the Swamp of Sorrows, in memory of the dead of that war.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Westfall",
		short = "Westfall borders the Kingdom of Stormwind and is mostly populated by humans not under the Alliance's complete control. The region was stolen right under the Alliance's nose by its own bitter people.",
		full = "Westfall borders the Kingdom of Stormwind and is mostly populated by humans not under the Alliance's complete control. The region was stolen right under the Alliance's nose by its own bitter people. This rich land has lain fallow since the Second War, but it is now held by the Defias Brotherhood. Stormwind claims the land as its own, but it has found little time to be concerned with it, with insufficient funds and might to retake the region. A handful of farmers still try to keep their land, and some even attempt a tithe to Stormwind every year, but most only grow enough to feed themselves. The Defias Brotherhood controls much of the region, focused in the southern area of Moonbrook.\n\nOnce a rich agricultural center, much of Westfall now lies fallow and forgotten. The Defias Brotherhood, renegade humans who wield secrecy and technology against Stormwind, control much of the area. Bandits and gnolls raid those farms that remain, and Stormwind's resources are stretched too thin to protect the beleaguered populace. Westfall has the mild temperatures of Elwynn, but winds batter it both from the sea and from Duskwood. The bare farmlands add little to break the wind, which can cut through clothing on a blustery day.\n\nWestfall is a region of rolling pastures and farms that were once beautiful and green, but now have become barren with drought and maltreatment at the hands of bandits. The grass is yellowed and the fields are infested with ravenous carrion birds and mechanical harvest watchers gone rogue. The outlawed Defias Brotherhood has gained a strong foothold in Westfall and controls several camps and farmsteads in the area. It is rumored that these bandits possess a large mine with an entrance somewhere in the small town of Moonbrook, and that they have connections with the kobolds that occupy the Jangolode Mine in Westfall and the various mines in Elwynn Forest.\n\nThe People's Militia has erected a last bastion of military power in the region at Sentinel Hill, from where they issue commands to anyone willing to aid the cause. Although most of the area's farms have fallen to disrepair and passed into control of the Defias, there are still a number of farmers who bravely (and desperately) cling to their holdings in spite of overwhelming odds.\n\nAlso, note that on PvP servers and even some PvE servers high-level Horde players enjoy killing human NPCs at Sentinel Hill.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Wetlands",
		short = "Mist lies over the Wetlands always, and the sky never quite clears. Ruins of Ironforge strongholds stand half-swallowed by the swamp, and murlocs and renegade orcs hold what the dwarves once built.",
		full = "Mist lies over the Wetlands always, and the sky never quite clears. Ruins of Ironforge strongholds stand half-swallowed by the swamp, and murlocs and renegade orcs hold what the dwarves once built.\n\nWhen the Old Horde came south, the Dragonmaw clan took the fortress of Grim Batol for their own, and the land paid for it: game grew scarce as orcs and dragons fed on it without pause, and the earth sickened into badland.\n\nGrim Batol did not stay Dragonmaw ground. The red dragonflight, freed of its enslavement to the orcs, turned on them and broke them; the survivors scattered into the wilds, never again the power they had been. The dwarves who came after sensed the mountain was still wrong beneath its silence, and left it. Alexstrasza and her consort Korialstrasz judged it the red flight's duty to seal the place, setting dragonkin to stand guard and bar anyone from entering.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Teldrassil",
		short = "Teldrassil was set ablaze by the Horde under Sylvanas Windrunner's order, its fall the reason the tree stands as it does now.",
		full = "Teldrassil was set ablaze by the Horde under Sylvanas Windrunner's order, its fall the reason the tree stands as it does now. Demolishers bearing arcane-enhanced payloads struck the great trunk while shaman in Darkshore called up winds to drive the flames higher, kindling the largest fire Azeroth had ever seen. Hundreds of night elves fled toward Darnassus as the World Tree burned above them. Survivors escaped through portals into Stormwind, filling Olivia's Pond and the Cathedral of Light with refugees, while others took to the beaches east of besieged Lor'danel to be carried off toward Azuremyst Isle. Even after the fighting ended, the great husk of the tree went on smoldering, a blackened trunk rising from the sea where a living forest once crowned the water.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Darkshore",
		short = "A low mist clings to Darkshore, and the night elves who once ruled here mostly leave it be.",
		full = "A low mist clings to Darkshore, and the night elves who once ruled here mostly leave it be. Ten thousand years past, before the seas broke the world apart, the twin cities of Ameth'Aran and Bashal'Aran stood on this coast, ruled by Athrikus Narassin. As the Sundering approached, he swore to save his people from ruin. He kept his word cruelly: he sealed their souls into gems, promising them life everlasting, while he drank their power for himself. Both cities still lie broken on the cliffs.\n\nLong after, when the Horde pushed north to burn Teldrassil, Darkshore became a battleground. Elune shrouded the coast in a lunar eclipse to strengthen Tyrande Whisperwind and her people, who drove the Forsaken from the land in hard fighting. Bashal'Aran's old ruins served as their base through the war, and it was there the tide finally turned in the Alliance's favor.\n\nWhen the fighting ended, little life remained in the mists but wildlife, and the wailing of dead who would not pass on.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Ashenvale",
		short = "Ashenvale is the ancestral home of the night elves, and its forests remember what was done to them.",
		full = "Ashenvale is the ancestral home of the night elves, and its forests remember what was done to them.\n\nWhen the orcs of the Warsong clan came during the Third War, they came first for lumber, felling trees the furbolgs could not defend. Grommash Hellscream broke both the furbolgs and the Sentinels sent against him. Cenarius came to restore what had been cut down, but the Burning Legion's masters turned Hellscream against him, and the demigod was slain in his own woods.\n\nCenturies later, when the Horde marched again on Darnassus, Ashenvale burned once more. Captain Delaryn Summermoon and her Sentinels dropped the bridges of the Falfarren River to slow the advance, but poison and fire took the outposts behind them. The village of Astranaar was put to the torch, its guards poisoned at their posts, and Captain Alennah Starsong fell with many of her Sentinels before the attack was turned back.\n\nThe forest still stands green and deep, its lakes clear under old boughs, though pockets of it never healed.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Thousand Needles",
		short = "The canyon runs deep and dry through the south of Kalimdor, its floor broken into towering mesas standing like teeth against the sky.",
		full = "The canyon runs deep and dry through the south of Kalimdor, its floor broken into towering mesas standing like teeth against the sky. Where it opens eastward, the stone gives way to the Shimmering Flats, a great salt pan so flat and empty it seems to belong to another world entirely.\n\nThe high mesas belong to the tauren, and Freewind Post stands among them as testament to a hard-won peace. With the Horde's aid, the tauren there fought back the centaur who prowled the canyon and drove off the Grimtotem tribe who coveted it for their own. That war was never fully settled; the Grimtotem remained a name spoken with suspicion in these parts, and when the Burning Legion later fell upon the Needles, it was the Grimtotem homeland they struck hardest, forcing Magatha Grimtotem to swallow her pride and call upon the Earthen Ring for aid.\n\nDown in the Shimmering Flats, a different rivalry played out. Gnomes and goblins built the Mirage Racetrack to settle, race after race, an argument neither side would ever let die: whose engineering was the finer. The track is gone to wreckage now, scattered rocket-car husks rusting in the salt.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Stonetalon Mountains",
		short = "Stonetalon Peak has always belonged to something older than the peoples who now climb it.",
		full = "Stonetalon Peak has always belonged to something older than the peoples who now climb it. Long before tauren or night elves kept vigil there, it was home to the Oracle, an immortal being who saw the strands of fate as the Earth Mother wove them. The night elves keep a barrow and a glade at the summit, where they commune with the spirits of nature, and the tauren hold the peak sacred alongside them, one of the few places in Kalimdor where the two peoples have long stood as neighbors rather than strangers.\n\nIn ancient times Elune blessed a fountain of health somewhere in the range. In later years that fountain was found corrupted, its waters spoiled by harpies who had taken the surrounding wyverns for their own. Thrall broke the harpies with Cairne Bloodhoof and his tauren at his side, winning a Glyph of Purification from centaur who guarded the fountain, and used it to cleanse the water once more.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Desolace",
		short = "In Desolace, the skulls of ancient kodo beasts stare soullessly from their graves, halfway buried in dust.",
		full = "In Desolace, the skulls of ancient kodo beasts stare soullessly from their graves, halfway buried in dust. The husks of long-dead trees jutting in gruesome angles from the gray ash are the only twisted remains of a verdant past.\n\nThis dour setting is violently jarred by the thunder of thousands of hooves and the clamor of armor and weaponry as the four tribes of vicious centaur wage war on all who enter their domains, including one another. Desolace is the home of the centaur. It was among the twisting cliffs of the western canyons that their race was born from the foul womb of Maraudon.\n\nProud, but sorrowful ruins of stone attest to the one-time glory of the Highborne night elves. Blasted in the depths of time by the shock waves of the Great Sundering, the ruins are inhabited now by all manner of foul creatures.\n\nDesolace today is a battleground for many of the opposing factions represented here. Apart from the tension between the Horde and the Alliance, at Shadowprey Village and Nijel's Point respectively, the Kolkar, the Gelkis, the Magram, and the Maraudine centaurs fight as much against each other as they do against the orcs and the humans. In the meantime, the demons and satyrs summoned by the Burning Blade increase the risk of a region-wide demonic infestation and present a major challenge for both the Horde and the Alliance. The naga presence to the northwest is also rapidly becoming a source of concern.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Feralas",
		short = "Feralas is a rainforest of ancient trees where the barren lands around it give way to green, its ruins scattered and half-swallowed by root and vine.",
		full = "Feralas is a rainforest of ancient trees where the barren lands around it give way to green, its ruins scattered and half-swallowed by root and vine. Most of them have long since fallen to the Gordunni ogres, whose taint spreads through the wilds like a rot wherever their war parties pass.\n\nDeep in these forests, Cho'gall once laid a trap of patience rather than force. He had long been hunted by Garona Halforcen, so he sent his Twilight's Hammer cultists away and waited alone in the mist for her to come. She struck, as he knew she would, and wounded him in the grappling that followed, but the ogre-mage proved the stronger. He broke her mind and bent it to his will, and left the forest with a new assassin at his side, bound for Silithus.\n\nThe greatest of the ruins, Dire Maul, became the seat of ogre power. Raiding parties poured out of it to burn villages and waylay travelers through the southern forests, while a deeper corruption spread through the wilds alongside them. Only when the trouble was traced back to the ruins themselves was it ended, in the fall of Immol'thar and Prince Tortheldrin within Dire Maul's halls.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Dustwallow Marsh",
		short = "Dustwallow Marsh has never truly belonged to anyone. It is a hot, fetid swamp fed by underground springs that keep it eternally wet, its trees so dense they blot out the sun, its waters thick with crocolisks and murlocs.",
		full = "Dustwallow Marsh has never truly belonged to anyone. It is a hot, fetid swamp fed by underground springs that keep it eternally wet, its trees so dense they blot out the sun, its waters thick with crocolisks and murlocs. In the south, black dragons gather in such numbers that folk call the place Wyrmbog, and the drakes there answer to no crown.\n\nJaina Proudmoore brought her people here after the war at Mount Hyjal, raising the city-state of Theramore on a rocky island off the eastern coast. Its walls gleam, but they do more to hold the Alliance in than to project its strength outward -- the garrison's numbers have been quietly thinning, desertion by desertion, for reasons no one in the city cares to explain.\n\nOn the marsh's western edge, the Stonemaul ogres opened Brackenwall Village to the Horde, giving it the only real foothold it has ever had here. Rexxar, the mok'nathal, won the ogres' loyalty by killing their tyrant Kor'gall and led them into alliance with the Horde. It did not last: the black dragonspawn fell upon Stonemaul Village in the south in a rout that broke the tribe, and the survivors fled north to Brackenwall, swearing revenge on the wyrms that had taken their home.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Tanaris",
		short = "Tanaris is a blazing sea of dunes and broken rock, where sandstorms sweep for miles beneath a cloudless sky. It was not always so.",
		full = "Tanaris is a blazing sea of dunes and broken rock, where sandstorms sweep for miles beneath a cloudless sky. It was not always so. Once this was lush jungle, home to tauren tribes and a province of the Gurubashi Empire, until the Great Sundering tore the world apart and left the region a desert. The Farraki trolls, stranded here when their homeland vanished beneath the waves, adapted to the heat and dust and became the sand trolls who hold to the old ways still.\n\nBeneath the dunes lie the Caverns of Time, ancestral home of the bronze dragonflight. When silithid swarms rose from hives in the desert's remote reaches and struck at Anachronos and the caverns themselves, the attack spilled westward into Silithus and became the War of the Shifting Sands, drawing the bronze dragons into open war to defend their home.\n\nThe Steamwheedle Cartel built its trade empire here at Gadgetzan and Steamwheedle Port, as close to their sunken homeland as the goblins can bear to settle.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Azshara",
		short = "Azshara is located in northeastern Kalimdor, east of Ashenvale, south of Winterspring, and north of Durotar. It is a beautiful coastal area cloaked in eternal autumn.",
		full = "Azshara is located in northeastern Kalimdor, east of Ashenvale, south of Winterspring, and north of Durotar. It is a beautiful coastal area cloaked in eternal autumn. The trees and other flora are tinged in brilliant oranges and reds, and nearer the coast, great cliffs and sandy beaches line the ocean. The region's inhabitants can make life hard for the nature lover, however. Enraged ghosts, vicious satyr, stalking naga and ferocious wildlife can quickly put an end to those who venture too far from the road.\n\nA shattered stretch of coastline on Kalimdor's northeast, Azshara was once the greatest night elf metropolis. The city fell millennia ago in the War of the Ancients, but a few ragged buildings perch on the cliffs overlooking similar ruins among the coral. Much of the city of Azshara fell into the ocean. The Horde has established a small outpost, Grim Ulang, in the area, but naga are a constant danger.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Felwood",
		short = "The trees of Felwood stand grey and rotted, their bark weeping corruption into soil that no longer remembers what it was to be clean.",
		full = "The trees of Felwood stand grey and rotted, their bark weeping corruption into soil that no longer remembers what it was to be clean. This sickness has a cause and a name.\n\nAs the Burning Legion pressed toward Mount Hyjal, Archimonde ordered this forest corrupted to break the night elves' defenses. The dreadlord Tichondrius carried out the work with a warlock relic, the Skull of Gul'dan, twisting the wildlife, the ancients, the very ground into what now stands as Felwood. Arthas Menethil later told Illidan Stormrage that the skull could be turned against the corruption it had made, and could feed Illidan's own hunger for power besides. Illidan went into Felwood, fought and slew Tichondrius, and took the skull for himself. For using the Legion's own power to do it, his brother Malfurion cast him out.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Un'Goro Crater",
		short = "Un'Goro Crater sits walled off from the deserts around it, a green wound in the earth where jungle grows thick and the creatures within answer to no law but their own.",
		full = "Un'Goro Crater sits walled off from the deserts around it, a green wound in the earth where jungle grows thick and the creatures within answer to no law but their own. Devilsaurs stalk the ferns, fire elementals circle a volcano at the crater's heart, and pylons stand on the ridges that no one has ever explained.\n\nIt is said the titans used this place, alongside lands far to the north and east, as a testing ground for the shaping of life, the crucible from which the wild gods themselves emerged. Whatever unseen power watches over Un'Goro, it does not hold to the usual silence of such things -- here it has always been free to interfere directly, gathering and studying every creature in the crater, old and new alike, without favor.\n\nAn expedition led by Williden Marshal once came to study the crater and found it far more savage than they had prepared for; their camps were overrun, and the survivors fled to higher ground at what became known as Marshal's Refuge. Even that shelter did not hold forever, and the expedition built again at Marshal's Stand, proof they had finally learned how to live in a place that was never meant to be lived in.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Moonglade",
		short = "A hilly forest hemmed in by mountains, Moonglade lies untouched by corruption, its lake, Elune'ara, named for the goddess herself. Countless mounds rise across the vale, each one a sanctum for druids in their long sleep.",
		full = "A hilly forest hemmed in by mountains, Moonglade lies untouched by corruption, its lake, Elune'ara, named for the goddess herself. Countless mounds rise across the vale, each one a sanctum for druids in their long sleep. Here tauren and night elves walk without quarrel, bound by reverence for nature rather than any banner, and the Moonglade Wardens see that no violence disturbs those who hold the Circle's favor.\n\nCenarius once dwelled here, in the years of the War of the Ancients, when Malfurion Stormrage brought Tyrande Whisperwind and his brother Illidan into the glade to beg the demigod's aid against the swelling numbers of the Legion. Cenarius himself has remained ever since.\n\nAt the lake's depths sleeps the demigod Omen, who rises each year near the time of the Lunar Festival before being lulled back to rest. The festival is held in Nighthaven on the glade's shore, where the mounds of sleeping druids lie undisturbed beneath the trees.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "The sands of Silithus cover the ruin of an empire. Long before the night elves held this corner of Kalimdor, the Aqir raised Ahn'Qiraj here, a temple-city of their people.",
		full = "The sands of Silithus cover the ruin of an empire. Long before the night elves held this corner of Kalimdor, the Aqir raised Ahn'Qiraj here, a temple-city of their people. When the Qiraji rose among them and turned the place to war, the night elves fought them back and sealed the survivors behind a Scarab Wall raised in the aftermath, trapping them within their own temple rather than destroying it.\n\nThe wall has held the Qiraji, but not their servants. The silithid bred by their masters were left outside the seal, and over the centuries they have spread across the desert until the ruins themselves seem to crawl with them. The night elves meant to stop an infestation before it began; the size of the silithid hives standing today is proof enough that they failed.\n\nThe Cenarion Circle keeps a permanent watch from Cenarion Hold, counting the silithid and weighing whether the threat sealed behind that wall is one Alliance and Horde will have to face together.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Winterspring",
		short = "Snow lies deep over Winterspring, and beneath it the land keeps old griefs. Ten thousand years past, the Highborne raised the city of Kel'Theril here.",
		full = "Snow lies deep over Winterspring, and beneath it the land keeps old griefs. Ten thousand years past, the Highborne raised the city of Kel'Theril here. From the temple at Eldarath they had stolen the Crystal of Zin-Malor, and when they turned its power to their own ends the crystal shattered and cursed them all. Kel'Theril withered under that curse until the Great Sundering broke it apart for good. Its ruins still stand, and the dead who once ruled there still wander them as ghosts, unable to leave what they built.\n\nThe lesson went unlearned. Roughly a hundred years before the Dark Portal opened, the Archmage Maenius led high elves out of Quel'Thalas into Winterspring, seeking the same crystal's shards. They found them, and like the Highborne before them were driven to madness by the artifact's touch, and died there. Now their ghosts too haunt the ruins of Kel'Theril, alongside the ones who cursed the place first.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Stormwind City",
		short = "The stones of Stormwind carry more grief than any human city on Azeroth, and more stubborn hope besides.",
		full = "The stones of Stormwind carry more grief than any human city on Azeroth, and more stubborn hope besides.\n\nWhen the Horde marched on the city, siege engines battered its walls through the night and warlocks burned its soldiers where they stood. The city held only because Anduin Lothar circled his knights around by sea and struck the orcs from behind while the gates opened and the defenders poured out to meet them. A year later the orcs returned and broke through. King Llane Wrynn was cut down by the assassin Garona, and Stormwind burned to ash. Its survivors fled north to Lordaeron in a fleet of small boats.\n\nThe city was rebuilt stone by stone by the Stonemasons' Guild, white and whole again, under the boy-king Varian. But the nobles who commissioned the work ran the treasury dry, and when Guildmaster Edwin VanCleef demanded the wages owed his men, the House of Nobles disbanded the guild instead. The riot that followed killed Queen Tiffin. Varian's fury drove the stonemasons from the city they had raised with their own hands; they fled into Westfall and became the Defias Brotherhood.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Warchief Thrall named this place for a friend he could no longer thank in person.",
		full = "Warchief Thrall named this place for a friend he could no longer thank in person. After Mount Hyjal, he led his people into a desert land he called Durotar, in memory of his father, and there raised a city he named Orgrimmar, in honor of Orgrim Doomhammer, the mentor who had shaped him. It rose quickly, walled and towered, part of it carved straight into the mountains that guard its back, built with the hands of goblins, tauren, trolls, and the Mok'Nathal Rexxar, in a Horde no longer bound by the bloodlust of its past but reaching, uncertainly, for peace.\n\nThat peace was tested when fire and earth turned against the city, tearing through its buildings until Thrall had the ruins rebuilt in iron and stone, harder to burn, harder to break. The city that emerged was more martial than the one before, its towers spiked, its banners red and black over every post.\n\nGrommash Hold still stands above it all, the seat from which each warchief has watched over the valleys below.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Ironforge",
		short = "Ironforge (displayed as the City of Ironforge in the overworld) is the capital city of the dwarves, proud members of the Alliance.",
		full = "Ironforge (displayed as the City of Ironforge in the overworld) is the capital city of the dwarves, proud members of the Alliance. Carved into the depths of Ironforge Mountain in northern Dun Morogh, it is the ancestral home of the dwarves and one of the oldest cities on Azeroth. The Council of Three Hammers rules over the city to ensure the fair and equal treatment of all dwarves within its walls from the High Seat. The city is also the capital of the Kingdom of Khaz Modan, which is ruled by the Bronzebeard clan.\n\nAn expansive underground city of craftsmen, explorers, miners, and warriors, famous for its industry and as an Alliance center of commerce, Ironforge is equal parts fortress and capital and a testament to the dwarves' strength and resilience. The city consists of a series of concentric rings, with the smaller levels deeper underground, all radiating out from the namesake Great Forge at its center. Ironforge is perhaps the most intricate of the Alliance cities, boasting many small passageways, shops built into the rock walls, and cavernous rooms. The feel of the city is a bustling, rowdy, and somewhat industrial one, where there are always a thousand things happening at any time of the day or night. However, it is predominantly safe-feeling and cozy; fires roar in the hearths of the inns and shops, and much dwarven laughing and frivolity is to be heard. Also, unlike Stormwind and Darnassus, the city is actually a massive cavern carved into the earth by the dwarves; the ceiling and floor are both hard stone.\n\nMainly because of the Deeprun Tram, linking Ironforge and Stormwind City, and the district of Tinker Town, Ironforge is one of the most racially diverse cities in the Alliance world. With the Council of Three Hammers uniting all three dwarven clans, Ironforge has recently welcomed Dark Iron dwarves and Wildhammer dwarves into Ironforge as well.\n\nThe collective frivolity, the bustling and gruff manner of the dwarves, and the proximity to many quest and raid areas have historically made Ironforge, along with Stormwind City, a popular place to idle.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Thunder Bluff",
		short = "Thunder Bluff rises on four windswept mesas above the grasslands of Mulgore, reached only by rope-and-wood elevators of tauren make, or by long bridges strung between the rises.",
		full = "Thunder Bluff rises on four windswept mesas above the grasslands of Mulgore, reached only by rope-and-wood elevators of tauren make, or by long bridges strung between the rises. Tents, longhouses, and painted totems crown each summit. For generations the tauren wandered as a nomadic people, harried without rest by the centaur who ranged across Kalimdor. It was Cairne Bloodhoof, chieftain of the Bloodhoof tribe, who ended that exile. When Warchief Thrall and his New Horde came to Mulgore during the Third War, their strength joined Cairne's own and together they broke the centaur and won the grasslands for the tauren at last. Upon the mesas Cairne raised a refuge open to every scattered tribe, and in time those tribes bent to his rule as one people, disagreeing sometimes on the path ahead but never on his wisdom to lead them.\n\nThe bluffs still bear the weight of that founding in their rises and bridges, in the tents of tribes gathered under one chieftain's roof.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "The night elves built Darnassus after the Third War, when their long immortality had failed them. Many could not bear the sudden weight of aging and frailty.",
		full = "The night elves built Darnassus after the Third War, when their long immortality had failed them. Many could not bear the sudden weight of aging and frailty. A number of grieving druids resolved to plant a new World Tree to restore their bond with the eternal world. With Malfurion Stormrage gone missing, Fandral Staghelm took up the mantle of Archdruid and led the effort. The tree they raised, Teldrassil, rose off the coast until its crown broke above the clouds, and among its boughs the night elves founded their city as a testament to their people's survival.\n\nDarnassus stands open to the sky, unlike the close, walled cities of the humans and dwarves. It is built around a broad lake, its shores joined by graceful bridges, its pathways carpeted in fallen leaves. The Temple of the Moon rises above the trees as the seat of High Priestess Tyrande Whisperwind and her Sisters of Elune, beside the colonnaded Hall of Justice where the Sentinels keep their watch. The city remains what it was built to be: a tranquil refuge, and a monument to a people learning to live with mortality.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Undercity",
		short = "Beneath the ruined palace of Lordaeron lie crypts and sewers older than the Scourge itself, where the poorest of the old kingdom once huddled among the dead.",
		full = "Beneath the ruined palace of Lordaeron lie crypts and sewers older than the Scourge itself, where the poorest of the old kingdom once huddled among the dead. It was here that Arthas Menethil meant to build the Scourge's seat of power, only to abandon the half-finished catacombs when the Lich King called him north.\n\nSylvanas Windrunner and her free-willed dead finished what Arthas began, twisting the tunnels into an unassailable stronghold, and named themselves the Forsaken. In the throne room they raised, a stone tomb honors King Terenas, crafted by the humans who once served him, though his ashes were spent long ago to raise Kel'Thuzad from death. A trail of blood still marks the floor by the throne, left by a crown that rolled from a dying king's head.\n\nRivers of poisoned sludge now run through every quarter, choking the air for the living. Yet for Sylvanas and her kind, it remains the only refuge left to them.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}
